contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amountA, uint amountB) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amountA) + (amountB)); require(amountA <= 1000000000000000000000000000000); require(amountB <= 1000000000000000000000000000000);
        require(address(this).balance >= amountA + amountB);

        uint startBalance = address(c).balance;
        uint startSelf = address(this).balance;

        c.deposit{value: amountA}(); if (__ESBMC_reverted()) return;
        c.deposit{value: amountB}(); if (__ESBMC_reverted()) return;

        uint midBalance = address(c).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(
            !reverted &&
            address(c).balance == startBalance &&
            midBalance == startBalance + amountA + amountB &&
            address(this).balance == startSelf
        );
    }

    receive() external payable {}
}

