pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amountA, uint256 amountB) internal {
        amountA = bound(amountA, 0, 1000000000000000000000000000000);
        amountB = bound(amountB, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amountA + amountB);
        uint startBalance = address(c).balance;
        uint startSelf = address(this).balance;
        try c.deposit{value: amountA}() {} catch { return; }
        try c.deposit{value: amountB}() {} catch { return; }
        uint midBalance = address(c).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted &&
            address(c).balance == startBalance &&
            midBalance == startBalance + amountA + amountB &&
            address(this).balance == startSelf);
    }

    function testFuzz_run(uint256 amountA, uint256 amountB) public {
        _run(amountA, amountB);
    }

    receive() external payable {}
}
